[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WellSource — Expert health guidance you can trust</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300..800;1,9..40,300..800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --teal: #02838D;
      --teal-dark: #026870;
      --teal-light: #E8F5F6;
      --charcoal: #231F20;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --coral: #E8734A;
      --coral-dark: #D4623B;
      --amber: #F59E0B;
      --amber-light: #FEF3C7;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 10px 30px rgba(0,0,0,0.10);
      --radius: 12px;
      --radius-sm: 8px;
      --radius-lg: 16px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: var(--charcoal);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    ul, ol { list-style: none; }
    img { max-width: 100%; display: block; }

    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

    /* ===== HEADER ===== */
    .header {
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      position: sticky;
      top: 0;
      z-index: 1000;
    }

    .header-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 24px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 24px;
      font-weight: 700;
      color: var(--teal);
    }

    .logo svg { flex-shrink: 0; }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 20px;
    }

    .header-actions a {
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-600);
      transition: color 0.2s;
    }

    .header-actions a:hover { color: var(--teal); }

    .btn-subscribe {
      background: var(--teal);
      color: var(--white) !important;
      padding: 8px 20px;
      border-radius: 24px;
      font-weight: 600;
      font-size: 14px;
      transition: background 0.2s;
    }

    .btn-subscribe:hover { background: var(--teal-dark); }

    .main-nav {
      display: flex;
      gap: 0;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      border-top: 1px solid var(--gray-100);
    }

    .nav-item {
      position: relative;
    }

    .nav-item > button {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 14px 20px;
      font-size: 15px;
      font-weight: 500;
      color: var(--gray-700);
      transition: color 0.2s, background 0.2s;
      border-bottom: 2px solid transparent;
    }

    .nav-item > button:hover,
    .nav-item.active > button {
      color: var(--teal);
      background: var(--teal-light);
    }

    .nav-item.active > button {
      border-bottom-color: var(--teal);
    }

    .nav-item > button svg {
      transition: transform 0.2s;
    }

    .nav-item.active > button svg {
      transform: rotate(180deg);
    }

    .mega-menu {
      display: none;
      position: absolute;
      top: 100%;
      left: 0;
      min-width: 520px;
      background: var(--white);
      border-radius: 0 0 var(--radius) var(--radius);
      box-shadow: var(--shadow-lg);
      padding: 24px 28px;
      z-index: 100;
      border: 1px solid var(--gray-200);
      border-top: 2px solid var(--teal);
    }

    .nav-item.active .mega-menu { display: block; }

    .mega-menu h4 {
      font-size: 12px;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--gray-400);
      margin-bottom: 12px;
      font-weight: 600;
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 6px 32px;
    }

    .mega-menu-grid a {
      font-size: 14px;
      color: var(--gray-700);
      padding: 6px 0;
      transition: color 0.15s;
      font-weight: 450;
    }

    .mega-menu-grid a:hover { color: var(--teal); }

    .mega-menu-section + .mega-menu-section {
      margin-top: 20px;
      padding-top: 16px;
      border-top: 1px solid var(--gray-100);
    }

    /* ===== TICKER ===== */
    .ticker-bar {
      background: var(--teal);
      overflow: hidden;
      white-space: nowrap;
      padding: 10px 0;
    }

    .ticker-track {
      display: inline-flex;
      animation: ticker-scroll 25s linear infinite;
    }

    .ticker-track:hover {
      animation-play-state: paused;
    }

    .ticker-item {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: var(--white);
      font-size: 14px;
      font-weight: 500;
      padding: 0 40px;
    }

    .ticker-item svg { flex-shrink: 0; opacity: 0.8; }

    .ticker-dot {
      width: 5px;
      height: 5px;
      background: rgba(255,255,255,0.4);
      border-radius: 50%;
      flex-shrink: 0;
    }

    @keyframes ticker-scroll {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    /* ===== HERO ===== */
    .hero {
      padding: 48px 0;
      background: linear-gradient(135deg, var(--teal-light) 0%, var(--white) 60%);
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1fr 380px;
      gap: 40px;
      align-items: start;
    }

    .hero-main {
      position: relative;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--amber-light);
      color: var(--amber);
      font-size: 13px;
      font-weight: 700;
      padding: 6px 14px;
      border-radius: 20px;
      margin-bottom: 16px;
      text-transform: uppercase;
      letter-spacing: 0.03em;
    }

    .hero-category {
      display: inline-block;
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--teal);
      margin-bottom: 12px;
    }

    .hero-title {
      font-size: 40px;
      font-weight: 700;
      line-height: 1.2;
      color: var(--charcoal);
      margin-bottom: 16px;
    }

    .hero-subtitle {
      font-size: 18px;
      line-height: 1.6;
      color: var(--gray-600);
      max-width: 560px;
    }

    .hero-image-placeholder {
      width: 100%;
      height: 320px;
      background: linear-gradient(145deg, #B2DFDB 0%, #80CBC4 50%, #4DB6AC 100%);
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .hero-image-placeholder::before {
      content: '';
      position: absolute;
      width: 120px;
      height: 120px;
      border-radius: 50%;
      background: rgba(255,255,255,0.2);
      top: 20%;
      right: 20%;
    }

    .hero-image-placeholder svg {
      opacity: 0.6;
    }

    /* Sidebar / Trending */
    .trending-sidebar {
      background: var(--white);
      border-radius: var(--radius);
      box-shadow: var(--shadow-md);
      padding: 24px;
    }

    .trending-sidebar h3 {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 20px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .trending-sidebar h3 svg { color: var(--coral); }

    .trending-item {
      display: flex;
      gap: 12px;
      padding: 14px 0;
      border-top: 1px solid var(--gray-100);
      cursor: pointer;
      transition: background 0.15s;
    }

    .trending-item:hover { background: var(--gray-50); margin: 0 -12px; padding-left: 12px; padding-right: 12px; border-radius: var(--radius-sm); }

    .trending-num {
      font-size: 28px;
      font-weight: 700;
      color: var(--gray-200);
      line-height: 1;
      min-width: 32px;
    }

    .trending-content { flex: 1; }

    .trending-tag {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--teal);
      margin-bottom: 4px;
    }

    .trending-title {
      font-size: 14px;
      font-weight: 600;
      line-height: 1.4;
      color: var(--charcoal);
    }

    /* ===== NEWSLETTER CTA ===== */
    .newsletter-cta {
      background: linear-gradient(135deg, var(--teal) 0%, #026870 100%);
      padding: 56px 0;
    }

    .newsletter-inner {
      text-align: center;
      max-width: 560px;
      margin: 0 auto;
    }

    .newsletter-inner h2 {
      font-size: 32px;
      font-weight: 700;
      color: var(--white);
      margin-bottom: 12px;
    }

    .newsletter-inner p {
      font-size: 16px;
      color: rgba(255,255,255,0.85);
      margin-bottom: 28px;
      line-height: 1.6;
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      max-width: 480px;
      margin: 0 auto 12px;
    }

    .newsletter-form input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid rgba(255,255,255,0.3);
      border-radius: 28px;
      font-size: 15px;
      background: rgba(255,255,255,0.12);
      color: var(--white);
      font-family: inherit;
      outline: none;
      transition: border-color 0.2s, background 0.2s;
    }

    .newsletter-form input::placeholder { color: rgba(255,255,255,0.55); }
    .newsletter-form input:focus { border-color: rgba(255,255,255,0.7); background: rgba(255,255,255,0.18); }

    .newsletter-form button {
      padding: 14px 32px;
      background: var(--coral);
      color: var(--white);
      border-radius: 28px;
      font-size: 15px;
      font-weight: 600;
      transition: background 0.2s, transform 0.1s;
      white-space: nowrap;
    }

    .newsletter-form button:hover { background: var(--coral-dark); transform: translateY(-1px); }

    .newsletter-privacy {
      font-size: 13px;
      color: rgba(255,255,255,0.55);
      margin-top: 8px;
    }

    .newsletter-privacy svg { vertical-align: middle; margin-right: 4px; }

    /* ===== HEALTH TOPICS CAROUSEL ===== */
    .health-topics {
      padding: 64px 0;
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 32px;
    }

    .section-header h2 {
      font-size: 28px;
      font-weight: 700;
    }

    .view-all {
      font-size: 14px;
      font-weight: 600;
      color: var(--teal);
      display: flex;
      align-items: center;
      gap: 4px;
      transition: gap 0.2s;
    }

    .view-all:hover { gap: 8px; }

    .carousel-wrapper {
      position: relative;
    }

    .carousel-track {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      -ms-overflow-style: none;
      padding: 8px 0;
    }

    .carousel-track::-webkit-scrollbar { display: none; }

    .topic-card {
      flex: 0 0 170px;
      text-align: center;
      cursor: pointer;
      transition: transform 0.2s;
    }

    .topic-card:hover { transform: translateY(-4px); }

    .topic-image {
      width: 140px;
      height: 140px;
      border-radius: 50%;
      margin: 0 auto 14px;
      overflow: hidden;
      box-shadow: var(--shadow-md);
      border: 3px solid var(--white);
    }

    .topic-image-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .topic-card h3 {
      font-size: 14px;
      font-weight: 600;
      color: var(--charcoal);
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-70%);
      width: 42px;
      height: 42px;
      border-radius: 50%;
      background: var(--white);
      box-shadow: var(--shadow-md);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 2;
      transition: box-shadow 0.2s, transform 0.2s;
      border: 1px solid var(--gray-200);
    }

    .carousel-btn:hover { box-shadow: var(--shadow-lg); transform: translateY(-70%) scale(1.05); }

    .carousel-btn.prev { left: -20px; }
    .carousel-btn.next { right: -20px; }

    /* ===== TOOLS SECTION ===== */
    .tools-section {
      padding: 64px 0;
      background: var(--gray-50);
    }

    .tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 32px;
    }

    .tool-feature-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 32px;
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-200);
    }

    .tool-feature-card h3 {
      font-size: 22px;
      font-weight: 700;
      margin-bottom: 12px;
    }

    .tool-feature-card > p {
      font-size: 15px;
      color: var(--gray-600);
      margin-bottom: 20px;
      line-height: 1.6;
    }

    .tool-feature-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 10px 24px;
      background: var(--teal);
      color: var(--white);
      border-radius: 24px;
      font-size: 14px;
      font-weight: 600;
      transition: background 0.2s;
      margin-bottom: 24px;
    }

    .tool-feature-cta:hover { background: var(--teal-dark); }

    .tool-sub-list {
      border-top: 1px solid var(--gray-100);
      padding-top: 20px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .tool-sub-item {
      display: flex;
      gap: 14px;
      align-items: flex-start;
    }

    .tool-sub-icon {
      width: 40px;
      height: 40px;
      border-radius: var(--radius-sm);
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      color: var(--teal);
    }

    .tool-sub-item h4 {
      font-size: 14px;
      font-weight: 600;
      margin-bottom: 2px;
    }

    .tool-sub-item p {
      font-size: 13px;
      color: var(--gray-500);
      line-height: 1.5;
    }

    /* Right-side tools list */
    .tools-list-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-200);
      overflow: hidden;
    }

    .tool-list-item {
      padding: 24px 28px;
      border-bottom: 1px solid var(--gray-100);
      transition: background 0.15s;
      cursor: pointer;
    }

    .tool-list-item:last-child { border-bottom: none; }
    .tool-list-item:hover { background: var(--gray-50); }

    .tool-list-item h4 {
      font-size: 16px;
      font-weight: 600;
      margin-bottom: 6px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .tool-list-item p {
      font-size: 14px;
      color: var(--gray-500);
      line-height: 1.5;
    }

    .tool-list-item .tool-cta-link {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      margin-top: 8px;
      font-size: 13px;
      font-weight: 600;
      color: var(--teal);
    }

    /* ===== RECOMMENDED READS ===== */
    .recommended-reads {
      padding: 64px 0;
    }

    .tabs {
      display: flex;
      gap: 8px;
      margin-bottom: 32px;
      flex-wrap: wrap;
    }

    .tab-btn {
      padding: 10px 22px;
      border-radius: 24px;
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-600);
      background: var(--gray-100);
      transition: all 0.2s;
    }

    .tab-btn:hover { background: var(--gray-200); }

    .tab-btn.active {
      background: var(--teal);
      color: var(--white);
    }

    .reads-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .read-card {
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-200);
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
      background: var(--white);
    }

    .read-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .read-card-image {
      height: 180px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .read-card-body {
      padding: 20px;
    }

    .read-card-tag {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--teal);
      margin-bottom: 8px;
    }

    .read-card-body h3 {
      font-size: 16px;
      font-weight: 600;
      line-height: 1.4;
      color: var(--charcoal);
    }

    /* ===== TRUST SECTION ===== */
    .trust-section {
      padding: 72px 0;
      background: linear-gradient(135deg, #F0F9F9 0%, var(--white) 100%);
    }

    .trust-section > .container > h2 {
      font-size: 32px;
      font-weight: 700;
      text-align: center;
      margin-bottom: 48px;
      color: var(--charcoal);
    }

    .trust-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 28px;
    }

    .trust-card {
      text-align: center;
      padding: 32px 20px;
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-200);
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .trust-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .trust-icon {
      width: 56px;
      height: 56px;
      border-radius: 50%;
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 16px;
      color: var(--teal);
    }

    .trust-card h3 {
      font-size: 17px;
      font-weight: 700;
      margin-bottom: 10px;
      color: var(--charcoal);
    }

    .trust-card p {
      font-size: 14px;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* ===== FEATURED PROGRAMS ===== */
    .featured-programs {
      padding: 64px 0;
    }

    .programs-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .program-card {
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-200);
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
      background: var(--white);
    }

    .program-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .program-image {
      height: 150px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .program-card h3 {
      padding: 16px;
      font-size: 15px;
      font-weight: 600;
      line-height: 1.4;
    }

    /* ===== LATEST VIDEOS ===== */
    .latest-videos {
      padding: 64px 0;
      background: var(--gray-50);
    }

    .videos-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .video-card {
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-200);
      background: var(--white);
      cursor: pointer;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .video-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .video-thumbnail {
      height: 160px;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .play-btn {
      position: absolute;
      width: 52px;
      height: 52px;
      border-radius: 50%;
      background: rgba(255,255,255,0.92);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: 0 2px 12px rgba(0,0,0,0.15);
      transition: transform 0.2s;
    }

    .video-card:hover .play-btn { transform: scale(1.1); }

    .video-card h3 {
      padding: 16px;
      font-size: 14px;
      font-weight: 600;
      line-height: 1.5;
    }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--charcoal);
      color: var(--white);
      padding: 56px 0 0;
    }

    .footer-newsletter {
      max-width: 560px;
      margin: 0 auto 48px;
      text-align: center;
    }

    .footer-newsletter p {
      font-size: 15px;
      color: rgba(255,255,255,0.7);
      margin-bottom: 20px;
      line-height: 1.6;
    }

