  <script>
    // Mega-menu toggle
    function toggleMenu(menuId) {
      var items = document.querySelectorAll('.nav-item');
      items.forEach(function(item) {
        if (item.dataset.menu === menuId) {
          item.classList.toggle('active');
        } else {
          item.classList.remove('active');
        }
      });
    }

    document.addEventListener('click', function(e) {
      if (!e.target.closest('.nav-item')) {
        document.querySelectorAll('.nav-item').forEach(function(item) {
          item.classList.remove('active');
        });
      }
    });

    // Health topics carousel
    function scrollCarousel(direction) {
      var track = document.getElementById('topicsCarousel');
      var scrollAmount = 200;
      track.scrollBy({ left: direction * scrollAmount, behavior: 'smooth' });
    }

    // Recommended reads tabs
    function switchTab(tab) {
      document.querySelectorAll('.tab-btn').forEach(function(btn) {
        btn.classList.toggle('active', btn.dataset.tab === tab);
      });

      document.querySelectorAll('.read-card').forEach(function(card) {
        var categories = card.dataset.categories.split(',');
        if (tab === 'all' || categories.indexOf(tab) !== -1) {
          card.style.display = '';
        } else {
          card.style.display = 'none';
        }
      });
    }

    // Newsletter form
    function handleNewsletterSubmit(e, form) {
      e.preventDefault();
      var input = form.querySelector('input[type="email"]');
      var btn = form.querySelector('button');
      var originalText = btn.textContent;
      btn.textContent = 'Subscribed!';
      btn.style.background = '#059669';
      input.value = '';
      setTimeout(function() {
        btn.textContent = originalText;
        btn.style.background = '';
      }, 2500);
    }

    // Duplicate ticker content for seamless loop
    (function() {
      var track = document.getElementById('tickerTrack');
      track.innerHTML += track.innerHTML;
    })();
  </script>

</body>
</html>
